-- Dynamic properties and team foundation. Apply after authentication is configured.
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 5 and 100),description text not null check(char_length(description) between 30 and 3000),price numeric(15,2) not null check(price>0),purpose text not null check(purpose in('sale','rent')),property_type text not null check(property_type in('house','apartment','villa','townhouse','land','commercial')),bedrooms integer not null default 0,bathrooms integer not null default 0,kitchen integer not null default 0,parking integer not null default 0,square_feet integer not null check(square_feet>=50),city text not null default 'Karachi',area text not null,address text not null,latitude double precision not null,longitude double precision not null,images text[] not null default '{}',status text not null default 'draft' check(status in('draft','published','archived','sold','rented')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists properties_owner_idx on public.properties(owner_id,created_at desc);create index if not exists properties_public_search_idx on public.properties(status,city,area,price,created_at desc);
alter table public.properties enable row level security;create policy "public reads published properties" on public.properties for select using(status='published' or owner_id=auth.uid() or public.is_admin());create policy "owners create properties" on public.properties for insert to authenticated with check(owner_id=auth.uid());create policy "owners update properties" on public.properties for update to authenticated using(owner_id=auth.uid() or public.is_admin()) with check(owner_id=auth.uid() or public.is_admin());create policy "owners delete properties" on public.properties for delete to authenticated using(owner_id=auth.uid() or public.is_admin());
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),workspace_owner_id uuid not null references auth.users(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,email text not null,role text not null check(role in('Manager','Viewer')),status text not null default 'invited' check(status in('active','invited')),created_at timestamptz not null default now(),unique(workspace_owner_id,email));
create index if not exists team_members_workspace_idx on public.team_members(workspace_owner_id,created_at);alter table public.team_members enable row level security;create policy "workspace reads team" on public.team_members for select to authenticated using(workspace_owner_id=auth.uid() or user_id=auth.uid());create policy "owners invite team" on public.team_members for insert to authenticated with check(workspace_owner_id=auth.uid());create policy "owners manage team" on public.team_members for update to authenticated using(workspace_owner_id=auth.uid()) with check(workspace_owner_id=auth.uid());create policy "owners remove team" on public.team_members for delete to authenticated using(workspace_owner_id=auth.uid());
